"use client";import {useEffect,useState}from"react";import type{Testimonial}from"../../../lib/testimonials";const blank=():Testimonial=>({id:crypto.randomUUID(),name:"",relation:"",text:"",rating:5});export default function Testimonials(){const[items,setItems]=useState<Testimonial[]>([]),[msg,setMsg]=useState("");useEffect(()=>{fetch("/api/testimonials").then(r=>r.json()).then(setItems)},[]);const edit=(i:number,k:keyof Testimonial,v:string|number)=>setItems(a=>a.map((x,n)=>n===i?{...x,[k]:v}:x));async function save(){setMsg("در حال ذخیره...");const r=await fetch("/api/testimonials",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(items)});setMsg(r.ok?"نظرها ذخیره شد.":"ذخیره انجام نشد.")}return <main className="admin"><div className="adminHead"><div><small>اعتمادسازی</small><h1>نظر والدین</h1></div><div><a href="/admin">بازگشت به پنل</a><a href="/" target="_blank">مشاهده سایت</a></div></div><div className="editor"><section><h2>نظرهای ثبت‌شده</h2>{items.map((x,i)=><div className="packageEdit" key={x.id}><label>نام<input value={x.name} onChange={e=>edit(i,"name",e.target.value)}/></label><label>پکیج یا نسبت<input value={x.relation} onChange={e=>edit(i,"relation",e.target.value)}/></label><label>متن نظر<textarea value={x.text} onChange={e=>edit(i,"text",e.target.value)}/></label><label>امتیاز (۱ تا ۵)<input type="number" min="1" max="5" value={x.rating} onChange={e=>edit(i,"rating",Number(e.target.value))}/></label><button className="danger" onClick={()=>setItems(a=>a.filter((_,n)=>n!==i))}>حذف نظر</button></div>)}<button className="addProduct" onClick={()=>setItems(a=>[...a,blank()])}>+ افزودن نظر جدید</button></section><button className="save" onClick={save}>ذخیره همه نظرها</button>{msg&&<p className="status">{msg}</p>}</div></main>}
